"""Freshness of a stored HTTP response, an RFC 9111 subset. See task.md."""

from __future__ import annotations

import re
from dataclasses import dataclass
from datetime import datetime, timezone

FRESH = "FRESH"
STALE = "STALE"
MUST_REVALIDATE = "MUST_REVALIDATE"


class HeaderError(ValueError):
    """Raised for a header that is not a well-formed HTTP-date."""


@dataclass(frozen=True)
class Result:
    verdict: str
    current_age: int
    freshness_lifetime: int


_DATE_RE = re.compile(
    r"(?:Mon|Tue|Wed|Thu|Fri|Sat|Sun), ([0-9]{2}) "
    r"(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec) ([0-9]{4}) "
    r"([0-9]{2}):([0-9]{2}):([0-9]{2}) GMT"
)
_MONTHS = "Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec".split()
_EPOCH = datetime(1970, 1, 1, tzinfo=timezone.utc)
_DIGITS = re.compile(r"[0-9]+")


def _parse_date(value: str) -> int:
    value = value.strip()
    m = _DATE_RE.fullmatch(value) if len(value) == 29 else None
    if m is None:
        raise HeaderError(f"malformed HTTP-date: {value!r}")
    day, mon, year, hh, mm, ss = m.groups()
    try:
        dt = datetime(
            int(year), _MONTHS.index(mon) + 1, int(day),
            int(hh), int(mm), int(ss), tzinfo=timezone.utc,
        )
    except ValueError as exc:
        raise HeaderError(f"invalid HTTP-date: {value!r}") from exc
    delta = dt - _EPOCH
    return delta.days * 86400 + delta.seconds


def _split_directives(text: str) -> list[str]:
    parts: list[str] = []
    cur: list[str] = []
    in_quote = False
    i = 0
    while i < len(text):
        c = text[i]
        if in_quote:
            cur.append(c)
            if c == "\\" and i + 1 < len(text):
                i += 1
                cur.append(text[i])
            elif c == '"':
                in_quote = False
        elif c == '"':
            in_quote = True
            cur.append(c)
        elif c == ",":
            parts.append("".join(cur))
            cur = []
        else:
            cur.append(c)
        i += 1
    parts.append("".join(cur))
    return parts


def _unquote(value: str) -> str:
    if len(value) >= 2 and value[0] == '"' and value[-1] == '"':
        return re.sub(r"\\(.)", r"\1", value[1:-1])
    return value


def _cache_control(headers: dict[str, str]) -> dict[str, str | None]:
    raw = None
    for k, v in headers.items():
        if k.lower() == "cache-control":
            raw = v
    out: dict[str, str | None] = {}
    if raw is None:
        return out
    for part in _split_directives(raw):
        part = part.strip()
        if not part:
            continue
        if "=" in part:
            name, value = part.split("=", 1)
            out[name.strip().lower()] = _unquote(value.strip())
        else:
            out[part.lower()] = None
    return out


def _number(cc: dict[str, str | None], name: str) -> int | None:
    value = cc.get(name)
    if value is None or not _DIGITS.fullmatch(value):
        return None
    return int(value)


def _header(headers: dict[str, str], name: str) -> str | None:
    for k, v in headers.items():
        if k.lower() == name:
            return v
    return None


def evaluate(
    response_headers: dict[str, str],
    request_headers: dict[str, str],
    request_time: int,
    response_time: int,
    now: int,
) -> Result:
    """Decide whether the stored response may be reused at `now`."""
    rsp_cc = _cache_control(response_headers)
    req_cc = _cache_control(request_headers)

    date_raw = _header(response_headers, "date")
    expires_raw = _header(response_headers, "expires")
    lastmod_raw = _header(response_headers, "last-modified")
    date = _parse_date(date_raw) if date_raw is not None else response_time
    expires = _parse_date(expires_raw) if expires_raw is not None else None
    last_mod = _parse_date(lastmod_raw) if lastmod_raw is not None else None

    age_raw = _header(response_headers, "age")
    age = 0
    if age_raw is not None and _DIGITS.fullmatch(age_raw.strip()):
        age = int(age_raw.strip())

    response_delay = response_time - request_time
    apparent_age = max(0, response_time - date)
    corrected_age = age + response_delay
    current_age = max(apparent_age, corrected_age) + (now - response_time)

    s_maxage = _number(rsp_cc, "s-maxage")
    max_age = _number(rsp_cc, "max-age")
    if s_maxage is not None:
        lifetime = s_maxage
    elif max_age is not None:
        lifetime = max_age
    elif expires is not None:
        lifetime = expires - date
    elif last_mod is not None:
        lifetime = (date - last_mod) // 10
    else:
        lifetime = 0
    lifetime = max(0, lifetime)

    req_max_age = _number(req_cc, "max-age")
    if req_max_age is not None:
        lifetime = min(lifetime, req_max_age)

    def result(verdict: str) -> Result:
        return Result(verdict, current_age, lifetime)

    if (
        "no-store" in rsp_cc
        or "no-cache" in rsp_cc
        or "must-revalidate" in rsp_cc
        or "no-cache" in req_cc
    ):
        return result(MUST_REVALIDATE)

    min_fresh = _number(req_cc, "min-fresh") or 0
    if lifetime > current_age + min_fresh:
        return result(FRESH)

    if "max-stale" in req_cc:
        if req_cc["max-stale"] is None:
            return result(FRESH)
        max_stale = _number(req_cc, "max-stale")
        if max_stale is not None and current_age - lifetime <= max_stale:
            return result(FRESH)

    return result(STALE)
